def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Markers are isolated cells of a color, distinct from the multicolored shape.
    candidates = []
    for color in counts:
        if color == bg:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if all(not any(0 <= r+dr < h and 0 <= c+dc < w and
                       grid[r+dr][c+dc] == color
                       for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
               for r, c in cells):
            candidates.append(color)
    marker = max(candidates, key=lambda x: counts[x])

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, marker)]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    pattern = [[grid[r][c] if grid[r][c] != marker else bg
                for c in range(c0, c1+1)] for r in range(r0, r1+1)]
    ph, pw = len(pattern), len(pattern[0])
    ar, ac = ph // 2, pw // 2

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                top, left = r-ar, c-ac
                for i in range(ph):
                    for j in range(pw):
                        rr, cc = top+i, left+j
                        if 0 <= rr < h and 0 <= cc < w and pattern[i][j] != bg:
                            out[rr][cc] = pattern[i][j]
    return out
